      got: 12.0,
      max: 24,
      annotatedHtml: `b肾上腺素受体阻断剂<br><span class="anno-ok">能抑制心脏的b受体，起到负性心率肌力传导作用<span class="anno-badge ok">🏆 阻断心脏 β1 三负效应精准命中 +2.5（补一句：使心输出量减少、心肌耗氧量降低）</span></span><br><span class="anno-err">能抑制容量血管和支气管的平滑肌上的b受体，起到扩张容量血管，降低前负荷，松弛支气管平滑肌作用<span class="anno-badge err">❌ 根源性方向写反(-3.0)：激动 β2 才是松弛支气管和舒张血管！普萘洛尔【阻断 β2 受体】会导致【支气管平滑肌收缩（诱发或加重支气管哮喘）】和【血管收缩（外周阻力初增、冠脉痉挛）】！扩张容量血管降前负荷的是【硝酸甘油】！</span></span><br><span class="anno-ok">抑制肾小球旁细胞上的b受体，抑制肾小球旁细胞的活化，避免释放肾素激活RAAS系统<span class="anno-badge ok">🏆 阻断肾小球旁器 β1 抑制肾素释放满分 +2.0！</span></span><br><span class="anno-miss">别的不记得了<span class="anno-badge err">⭕ 漏写代谢作用与另外两大共性(-2.5)：① 代谢：抑制交感兴奋所致的脂肪与糖原分解，延缓用胰岛素后低血糖恢复并【掩盖低血糖心悸预警症状】；② 【内在拟交感活性（ISA）】（如吲哚洛尔）；③ 【膜稳定作用】（高浓度阻 Na+ 通道）</span></span><br><span class="anno-ok">普萘洛尔是非选择性的b受体阻断剂，能治疗心力衰竭，高血压，心绞痛<span class="anno-badge ok">✓ 机制（非选择性阻断 β1/β2）与三大核心适应证命中 +4.0</span></span> <span class="anno-miss">[⭕ 漏写两大适应证(-2.0)：④ 【快速型心律失常】（窦速、交感兴奋室上性/室性心律失常）；⑤ 【甲状腺功能亢进症（及甲亢危象）】辅助治疗]</span><br><span class="anno-ok">不良反应主要是存在停药反跳，应当缓慢减量停药<span class="anno-badge ok">✓ 反跳现象与渐减停药原则 +1.5</span></span> <span class="anno-miss">[⭕ 漏写核心不良反应(-2.5)：① 【诱发或加重支气管哮喘】（阻断 β2）；② 心血管抑制（严重心动过缓、房室传导阻滞、诱发急性心衰、四肢冰冷）；③ 掩盖低血糖心悸]</span><br><span class="anno-ok">禁忌症有心率过缓，变异型心绞痛<span class="anno-badge ok">✓ 窦性心动过缓、变异型心绞痛命中 +2.0</span></span>，<span class="anno-warn">心律不齐<span class="anno-badge warn">⚠️ 表述纠偏：普萘洛尔本身用于治【快速型】心律失常，禁忌的是【重度房室传导阻滞】等缓慢型心律失常！且因前面 β2 写反，此处漏写了头号禁忌证【支气管哮喘】与【急性左心衰（失代偿期）】(-2.0)</span></span>`,
