    doubtsQA: [
      {
        q: "疑点 1：长春新碱和紫杉醇有点分不清，怎么记住谁是抑制聚合、谁是促进聚合并抑制解聚？",
        a: "这两个药都是作用于 **M 期（有丝分裂期）**、拿**微管蛋白（纺锤体）**开刀的植物药，但动手方式截然相反！\n\n用四字口诀**【春散紫聚】**（或画面记忆**“长春拆桥，紫杉焊死”**），一辈子不会混：\n1. **长春新碱（Vincristine）——“春散（春天冰消瓦解散开 / 拆桥）”**：\n   • **机制**：结合微管蛋白，**【抑制】微管蛋白聚合** → 纺锤丝根本组装不起来（把桥拆了），有丝分裂停在中期。\n   • **特征毒性**：神经轴突运输也靠微管，微管散架导致**【外周神经炎】（指趾麻木、腱反射消失）**，但几乎无骨髓抑制。\n2. **紫杉醇（Paclitaxel）——“紫聚（紫杉木坚硬死板聚成团 / 焊死）”**：\n   • **机制**：**【促进】微管蛋白聚合并【抑制】微管解聚** → 微管变成一团拆不开的死疙瘩（把桥焊死了），纺锤体失去动态牵拉染色体的功能，有丝分裂同样停在中期！\n   • **特征毒性**：骨髓抑制、周围神经毒性及严重过敏反应。"
      },
      {
        q: "疑点 2：选择第 8 题一点不记得，而且简答题里博来霉素、顺铂、长春新碱的器官毒性全搞混了，怎么一口气背死？",
        a: "传统化疗药除了“骨髓抑制、胃肠反应、脱发”三大共性外，最爱考的就是**【五大特征性器官毒性】**！用下面这 **5 句谐音画面口诀**，1 分钟把单选第 8 题和简答第 1 题同时焊死：\n\n1. **环磷酰胺 → 出血性膀胱炎（美司钠解救）**\n   • 口诀：**“环磷膀胱尿血，找美司钠救”**（体内代谢产物**丙烯醛**经尿排泄灼伤膀胱，用**美司钠**中和）。\n2. **多柔比星（阿霉素） → 剂量依赖性心脏毒性**\n   • 口诀：**“林黛玉多柔弱，心脏不好”**（引起心肌病变与心衰，用铁螯合剂**右雷佐生**防治）。\n3. **博来霉素 → 间质性肺炎与肺纤维化（单选第 8 题！）**\n   • 口诀：**“刘博士肺气肿 / 博击长空伤了肺”**（肺部缺乏灭活博来霉素的水解酶，导致**剂量限制性肺纤维化**；且它和长春新碱一样**几乎无骨髓抑制**！）。\n4. **顺铂 → 肾毒性 + 耳毒性 + 剧烈呕吐**\n   • 口诀：**“顺风耳、顺水肾”**（顺铂伤**肾**和**耳**，需大剂量水化利尿保护肾脏；注意：**奥沙利铂**才是遇冷诱发外周神经毒，**顺铂**主打**肾耳毒**！）。\n5. **长春新碱 → 外周神经炎（周围神经毒性）**\n   • 口诀：**“长春藤缠绕外周神经”**（引起指趾麻木、外周神经炎，且**几乎无骨髓抑制**）。"
      },
      {
        q: "疑点 3：名词解释第 3 题 Multidrug resistance (MDR) 那个把药泵出去的蛋白叫什么？",
        a: "那个赫赫有名的跨膜主动外排泵蛋白就叫 **【P-糖蛋白（P-glycoprotein，简称 P-gp）】**（由多药耐药基因 `MDR1` 编码，属于 ABC 转运蛋白超家族）！\n\n答 `MDR（多药耐药性）` 名解时，记住 **“一定一泵”** 拿满分：\n• **一定（交叉耐药定义，最关键采分点）**：肿瘤细胞接触**一种**抗肿瘤药产生耐药后，同时对多种**化学结构不同、作用靶点与机制完全迥异**的其他抗肿瘤药产生**交叉耐药**的现象。\n• **一泵（核心分子机制）**：细胞膜上 ATP 依赖性跨膜外排泵 **P-糖蛋白（P-gp）** 过度表达，将进入胞内的化疗药不断主动泵出胞外。"
      }
    ],

