        a: "1. 替尼类（胞内阻断酪氨酸激酶）：\n   • 伊马替尼：抑制【Bcr-Abl】融合蛋白酪氨酸激酶 → 首选【慢性粒细胞白血病（CML）】；\n   • 吉非替尼：抑制【EGFR】酪氨酸激酶 → 非小细胞肺癌。\n2. 单抗类（胞外结合特异抗原）：\n   • 曲妥珠单抗：靶向结合【HER2】→ HER2 过表达【乳腺癌】；\n   • 利妥昔单抗：靶向结合【CD20】→ B 细胞非霍奇金淋巴瘤。"
