        a: "之所以觉得这三章乱，是因为它们都在围绕**【中枢抑制】**打转！其实整整三章只干了 **2 件事**：要么**【开门放 Cl- 进来（增强 GABA 抑制）】**，要么**【关门挡 Na+/Ca2+ 进来（阻止神经元放电）】**！\n\n用这张**【中枢上篇·两大通道统摄表】**，30 秒把三章彻底焊死：\n\n1. **第一阵营：开 Cl- 门（作用于 GABAA 受体复合物 → 镇静催眠与静脉全麻）**\n   • **地西泮（苯二氮䓬类）**：增加 Cl- 通道开放**【频率】**（安全性高）→ 抗焦虑、镇静催眠、抗惊厥、**癫痫持续状态静注首选**、中枢肌松。解毒药：**氟马西尼**。\n   • **苯巴比妥（巴比妥类）**：延长 Cl- 通道开放**【时间】**（大剂量直接开通道，易呼吸抑制、有宿醉、诱导肝药酶）→ 急性中毒用**碳酸氢钠碱化尿液**促排。\n   • **唑吡坦 / 扎来普隆（新型非苯二氮䓬）**：只挑 GABAA 的 **α1 亚型**激动 → 只管速效催眠，不破坏睡眠结构（注：**丁螺环酮**是个异类，不碰 GABA，它是**部分激动 5-HT1A 受体**，只管慢效抗焦虑）。\n   • **丙泊酚 / 依托咪酯 / 硫喷妥钠（静脉全麻药）**：也是增强 GABAA！记住各自标签：**丙泊酚**（快进快出、抗呕吐，短小手术王牌）；**硫喷妥钠**（脂溶性极高，靠**再分布**迅速苏醒）；**依托咪酯**（对心血管影响最小）。\n\n2. **第二阵营：关 Na+ / Ca2+ 门（阻止高频放电 → 局麻药与抗癫痫药）**\n   • **局麻药（普鲁卡因、利多卡因）**：直接堵死外周神经电压门控 **Na+ 通道**，不让痛觉传上去！\n   • **苯妥英钠、卡马西平（抗癫痫主力）**：堵死中枢病灶电压依赖性 **Na+ 通道**！**苯妥英钠**管**大发作**（但**小发作禁用/加重**！）；**卡马西平**管**复杂部分性发作 + 三叉神经痛首选**。\n   • **乙琥胺（专治小发作）**：不堵 Na+，专门堵丘脑神经元 **T 型 Ca2+ 通道** → **失神发作（小发作）唯一专一首选**！\n   • **丙戊酸钠（全能兜底王）**：Na+ 门也堵、Ca2+ 门也堵、还升高脑内 GABA → **广谱抗癫痫（大发作合并小发作首选）**！"
